import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"1. Capítulo I: Diagnóstico (Ejemplo Real)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/1_Capitulo_I_Diagnostico.md","filePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/1_Capitulo_I_Diagnostico.md"}'),n={name:"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/1_Capitulo_I_Diagnostico.md"};function r(l,a,s,c,d,p){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="_1-capitulo-i-diagnostico-ejemplo-real" tabindex="-1">1. Capítulo I: Diagnóstico (Ejemplo Real) <a class="header-anchor" href="#_1-capitulo-i-diagnostico-ejemplo-real" aria-label="Permalink to &quot;1. Capítulo I: Diagnóstico (Ejemplo Real)&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Instrucciones de Uso:</strong> Este capítulo narra cómo llegaste a la comunidad y qué encontraste. Recuerda redactar siempre en <strong>Tercera Persona</strong> (&quot;se realizó&quot;, &quot;el equipo investigó&quot;, no &quot;nosotros investigamos&quot;).</p></div><hr><h2 id="capitulo-i" tabindex="-1">CAPÍTULO I <a class="header-anchor" href="#capitulo-i" aria-label="Permalink to &quot;CAPÍTULO I&quot;">​</a></h2><h2 id="el-diagnostico-participativo" tabindex="-1">EL DIAGNÓSTICO PARTICIPATIVO <a class="header-anchor" href="#el-diagnostico-participativo" aria-label="Permalink to &quot;EL DIAGNÓSTICO PARTICIPATIVO&quot;">​</a></h2><h3 id="_1-1-descripcion-de-la-comunidad" tabindex="-1">1.1 Descripción de la Comunidad <a class="header-anchor" href="#_1-1-descripcion-de-la-comunidad" aria-label="Permalink to &quot;1.1 Descripción de la Comunidad&quot;">​</a></h3><p>El proyecto se llevó a cabo en <strong>[la Unidad Educativa Nacional &quot;Simón Bolívar&quot;]</strong>, ubicada geográficamente en <strong>[la parroquia Juan Ignacio Montilla, municipio Valera, estado Trujillo]</strong>. Esta institución fue fundada en el año <strong>[1985]</strong> y actualmente cuenta con una matrícula de <strong>[500 estudiantes de educación media general]</strong>. Su misión principal es <strong>[brindar educación gratuita y de calidad a los jóvenes del sector]</strong>.</p><p>El contacto inicial se realizó a través de <strong>[la directora de la institución, la Prof. Carmen Rojas]</strong>, quien facilitó el acceso a las instalaciones para el desarrollo del Proyecto Sociotecnológico del PNFI.</p><h3 id="_1-2-planteamiento-del-problema" tabindex="-1">1.2 Planteamiento del Problema <a class="header-anchor" href="#_1-2-planteamiento-del-problema" aria-label="Permalink to &quot;1.2 Planteamiento del Problema&quot;">​</a></h3><p><em>Aquí relatas el &quot;Tronco&quot; y las &quot;Raíces&quot; de tu Árbol de Problemas.</em></p><p>Durante los recorridos iniciales y la aplicación de los instrumentos de recolección de datos (guías de observación y entrevistas al personal docente), el equipo investigador detectó una carencia tecnológica significativa en la institución. Se evidenció como problema central <strong>[una alta inoperatividad de los equipos de computación ubicados en el Laboratorio de Informática]</strong>.</p><p>Al indagar en las causas (raíces) de esta problemática, se comprobó que <strong>[el 80% de las fallas se deben a la ausencia prolongada de mantenimiento preventivo y a fluctuaciones eléctricas sin el respaldo de reguladores de voltaje]</strong>. Adicionalmente, se notó un marcado <strong>[desconocimiento técnico por parte del personal administrativo sobre el uso de software libre]</strong>.</p><p>Esta situación genera efectos negativos considerables en la dinámica institucional, tales como <strong>[un atraso crónico en la carga de notas de los estudiantes y la imposibilidad de impartir clases prácticas de tecnología]</strong>, mermando la calidad educativa general del plantel.</p><h3 id="_1-3-objetivos-del-proyecto" tabindex="-1">1.3 Objetivos del Proyecto <a class="header-anchor" href="#_1-3-objetivos-del-proyecto" aria-label="Permalink to &quot;1.3 Objetivos del Proyecto&quot;">​</a></h3><p><em>Los objetivos nacen directamente de tu &quot;Árbol de Objetivos&quot;. Toda meta inicia con un verbo en infinitivo (Reparar, Optimizar, Instalar).</em></p><p><strong>Objetivo General:</strong></p><ul><li><strong>[Recuperar y optimizar al 100% la operatividad de los equipos de computación del laboratorio de la U.E.N. &quot;Simón Bolívar&quot;, acompañado de la alfabetización tecnológica del personal administrativo.]</strong></li></ul><p><strong>Objetivos Específicos:</strong><em>Los objetivos específicos son los escalones para alcanzar el general (coinciden con los &quot;Medios&quot; de tu árbol).</em></p><ol><li><strong>[Diagnosticar el estado actual de hardware y software de cada estación de trabajo.]</strong></li><li><strong>[Ejecutar el mantenimiento preventivo y correctivo (limpieza física y reemplazo de componentes) a nivel de hardware.]</strong></li><li><strong>[Instalar y configurar el sistema operativo Canaima GNU/Linux bajo los estándares de la Ley de Infogobierno.]</strong></li><li><strong>[Capacitar al personal docente y administrativo en el uso de herramientas ofimáticas libres (LibreOffice).]</strong></li></ol><h3 id="_1-4-justificacion-importancia-del-proyecto" tabindex="-1">1.4 Justificación (Importancia del Proyecto) <a class="header-anchor" href="#_1-4-justificacion-importancia-del-proyecto" aria-label="Permalink to &quot;1.4 Justificación (Importancia del Proyecto)&quot;">​</a></h3><p><em>¿Por qué la UPTT te aprueba hacer esto?</em></p><p>El presente proyecto se justifica desde un punto de vista técnico y social. En el ámbito técnico, permite prolongar la vida útil del hardware institucional mediante la aplicación de <strong>[soporte técnico y mantenimiento preventivo]</strong>, evitando la obsolescencia programada. En el ámbito social, la intervención permite <strong>[reactivar las clases de informática, beneficiando a más de 500 estudiantes de manera directa]</strong>.</p><p>Académicamente, este trabajo cumple con las exigencias del <strong>Reglamento del Proyecto Socio Integrador/Tecnológico (PSI/T)</strong> de la UPTT, enmarcando la investigación en la línea matriz de <strong>Informática Aplicada</strong>, demostrando la integración de saberes teóricos en un contexto real para la transformación de la comunidad.</p>',23)])])}const g=e(n,[["render",r]]);export{m as __pageData,g as default};
